import{_ as o,C as a,c as i,o as s,aj as l,G as n,w as u}from"./chunks/framework.Bfdr4H5E.js";const w=JSON.parse('{"title":"Procedures Manual","description":"","frontmatter":{"outline":"deep","prev":{"text":"Trading Plan – Explanatory Notes","link":"/trading-with-pav/trading-plan-explanatory-notes"},"next":{"text":"Trading Plan Summary Details","link":"/trading-with-pav/trading-plan-summary-details"}},"headers":[],"relativePath":"trading-with-pav/procedures-manual.md","filePath":"trading-with-pav/procedures-manual.md"}'),c={name:"trading-with-pav/procedures-manual.md"};function d(p,e,m,h,f,y){const r=a("GraphComment"),t=a("ClientOnly");return s(),i("div",null,[e[0]||(e[0]=l('<h1 id="procedures-manual" tabindex="-1">Procedures Manual <a class="header-anchor" href="#procedures-manual" aria-label="Permalink to &quot;Procedures Manual&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#procedures-manual-1">Procedures Manual</a></li><li><a href="#sample-procedures-manual">Sample Procedures Manual</a></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="procedures-manual-1" tabindex="-1">Procedures Manual <a class="header-anchor" href="#procedures-manual-1" aria-label="Permalink to &quot;Procedures Manual&quot;">​</a></h2><p>A career as a military helicopter pilot. Effective command of an S-70A-9 Black Hawk requires the use of checklists for all standard routines and procedures, in order to minimize the likelihood of error, and ensure maximum “brain space” available for mission management and maintenance of situational awareness.</p><p>Trading is the same. Consistent use of your checklists will minimize the likelihood of procedural error.</p><p>Plus, as you become more familiar with your checklists these procedures will require less conscious attention, allowing greater focus on price action in order to remain in sync with the shifting forces of supply and demand.</p><p>Trading success requires consistent and disciplined application of our trading plan. The best way I know of to turn your plan into disciplined and consistent actions, is to create a checklist of procedures you will follow in applying your plan.</p><p>Our checklist is documented in a procedures manual.</p><h2 id="sample-procedures-manual" tabindex="-1">Sample Procedures Manual <a class="header-anchor" href="#sample-procedures-manual" aria-label="Permalink to &quot;Sample Procedures Manual&quot;">​</a></h2><p>The remainder of this chapter provides a sample procedures manual.</p><p><strong>PLEASE NOTE</strong>: This is just an example. Consider using it as a template for creation of your own procedures manual, amending as required to suit your own circumstances and needs.</p><p>The procedures manual contains the following sections:</p><ul><li>Trading Plan Summary Details</li><li>Emergency Contacts</li><li>Screen Setups</li><li>Routines <ul><li>Pre-Session</li><li>During Session</li><li>Post-Session</li></ul></li><li>Contingency Management</li><li>Action Affirmation (AA) Statements</li><li>Longer Term Reviews</li></ul><p>In most cases, the procedures have already been discussed in previous sections of the course articles, and will therefore create some duplication in content. However, they’ve been reproduced here in full in order to demonstrate the format and content of our procedures manual.</p><p>The procedures manual is quite detailed, and constantly referring to the manual can be quite distracting (I find that anyway!!). Please persevere though while you’re first learning. As you gain experience, the intent is that you won’t need to refer to these procedures for every step – they’ll become habit.</p><p>In time, you’ll probably be able to operate with a 1-page summary checklist. Eventually they’ll become internalized and you can trade without reference to any document.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',17)),n(t,null,{default:u(()=>[n(r)]),_:1})])}const b=o(c,[["render",d]]);export{w as __pageData,b as default};
